const BUILTIN_BRAND_LOGOS={"Maruti Suzuki": "brand-logos/suzuki.png", "Hyundai": "brand-logos/hyundai.png", "Tata": "brand-logos/tata.png", "Mahindra": "brand-logos/mahindra.png", "Toyota": "brand-logos/toyota.png", "Kia": "brand-logos/kia.png", "Honda": "brand-logos/honda.png", "Renault": "brand-logos/renault.png", "Nissan": "brand-logos/nissan.png", "Skoda": "brand-logos/skoda.png", "Volkswagen": "brand-logos/volkswagen.png", "MG": "brand-logos/mg.png", "Ford": "brand-logos/ford.png", "Chevrolet": "brand-logos/chevrolet.png", "Fiat": "brand-logos/fiat.png", "Jeep": "brand-logos/jeep.png", "Citroen": "brand-logos/citroen.png", "BYD": "brand-logos/byd.png", "Isuzu": "brand-logos/isuzu.png", "Force": "brand-logos/force-motors.png", "Datsun": "brand-logos/datsun.png", "Mitsubishi": "brand-logos/mitsubishi.png", "Mercedes-Benz": "brand-logos/mercedes-benz.png", "BMW": "brand-logos/bmw.png", "Audi": "brand-logos/audi.png", "Volvo": "brand-logos/volvo.png", "Land Rover": "brand-logos/land-rover.png", "Jaguar": "brand-logos/jaguar.png", "Lexus": "brand-logos/lexus.png", "Porsche": "brand-logos/porsche.png", "MINI": "brand-logos/mini.png", "Bentley": "brand-logos/bentley.png", "Rolls-Royce": "brand-logos/rolls-royce.png", "Lamborghini": "brand-logos/lamborghini.png", "Ferrari": "brand-logos/ferrari.png", "Maserati": "brand-logos/maserati.png", "Aston Martin": "brand-logos/aston-martin.png", "McLaren": "brand-logos/mclaren.png", "Tesla": "brand-logos/tesla.png", "Hindustan Motors": "brand-logos/hindustan-motors.png", "Premier": "brand-logos/premier.png", "Opel": "brand-logos/opel.png", "Daewoo": "brand-logos/daewoo.png", "SsangYong": "brand-logos/ssangyong.png", "Peugeot": "brand-logos/peugeot.png", "ICML": "brand-logos/icml.jpg"};

function vehicleCatalog(){const result=Object.assign(Object.create(null),CARS);for(const b of state.settings?.brandCatalog||[])result[b.name]=b.models||[];return result;}
function vehicleBrandLogo(name){return (state.settings?.brandCatalog||[]).find(b=>b.name===name)?.logo||BUILTIN_BRAND_LOGOS[name]||'';}
function brandLogoMarkup(name){const src=vehicleBrandLogo(name);return src?`<span class="brand-logo-tile"><img src="${esc(src)}" alt="" loading="lazy" width="100" height="60"></span>`:`<span class="brand-logo-tile brand-logo-fallback">${esc(initials(name))}</span>`;}
let brandLogoDraft='';let brandLogoLoading=false;
function brandEditor(name=''){
 if(role!=='employer'||!session?.admin)return;
 const existing=(state.settings.brandCatalog||[]).find(b=>b.name===name);
 brandLogoDraft=existing?.logo||'';brandLogoLoading=false;
 openModal(name?'Edit brand':'Add brand',`<form id="brand-editor"><input type="hidden" name="original" value="${esc(name)}"><div class="form-grid">${field('Brand name','brandName',name,'text',true)}<div class="form-group full"><label for="brand-models">Models (one per line or separated by commas)</label><textarea id="brand-models" name="models" rows="4" maxlength="6000">${esc((vehicleCatalog()[name]||[]).join('\n'))}</textarea></div><div class="form-group full"><label for="brand-logo-upload">Brand logo (optional)</label><input id="brand-logo-upload" type="file" accept="image/png,image/jpeg,image/webp"><p class="notice-inline">PNG, JPG or WebP. Up to 2 MB. Your image is resized for the catalog.</p><div id="brand-logo-preview">${brandLogoMarkup(name)}</div><button type="button" class="btn small light" data-action="clear-brand-logo">Clear selected logo</button></div></div><p id="brand-editor-error" class="error" role="alert"></p></form>`,`<button class="btn light" type="reset" form="brand-editor">Clear</button><button class="btn primary" type="submit" form="brand-editor">Save brand</button>`);
}
async function readBrandLogo(file){
 if(!file)return '';
 if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw new Error('Choose a PNG, JPG or WebP image smaller than 2 MB.');
 const url=URL.createObjectURL(file);
 try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('This image could not be opened.'));image.src=url});
 const canvas=document.createElement('canvas');canvas.width=192;canvas.height=112;const c=canvas.getContext('2d');const scale=Math.min(176/image.naturalWidth,96/image.naturalHeight);const w=image.naturalWidth*scale,h=image.naturalHeight*scale;c.drawImage(image,(192-w)/2,(112-h)/2,w,h);const data=canvas.toDataURL('image/webp',.85);if(data.length>32000)throw new Error('This image is too detailed. Choose a simpler logo.');return data;
 }finally{URL.revokeObjectURL(url)}
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='add-brand')brandEditor();if(b.dataset.action==='edit-brand')brandEditor(b.dataset.brand);if(b.dataset.action==='clear-brand-logo'){brandLogoDraft='';const input=document.getElementById('brand-logo-upload');if(input)input.value='';document.getElementById('brand-logo-preview').innerHTML='';}});
document.addEventListener('change',async event=>{if(event.target.id!=='brand-logo-upload')return;const form=event.target.closest('form');const error=form.querySelector('#brand-editor-error');brandLogoLoading=true;error.textContent='';try{brandLogoDraft=await readBrandLogo(event.target.files[0]);if(!form.isConnected)return;form.querySelector('#brand-logo-preview').innerHTML=brandLogoDraft?`<span class="brand-logo-tile"><img src="${brandLogoDraft}" alt="Selected brand logo"></span>`:'';}catch(e){brandLogoDraft='';event.target.value='';error.textContent=e.message;}finally{brandLogoLoading=false;}});
document.addEventListener('reset',event=>{if(event.target.id!=='brand-editor')return;brandLogoDraft='';document.getElementById('brand-logo-preview').innerHTML='';document.getElementById('brand-editor-error').textContent='';});
document.addEventListener('submit',event=>{
 if(event.target.id!=='brand-editor')return;event.preventDefault();if(role!=='employer'||!session?.admin)return;
 const f=event.target,error=f.querySelector('#brand-editor-error');if(brandLogoLoading){error.textContent='Wait for the logo to finish loading.';return;}
 const d=new FormData(f),original=String(d.get('original')||''),name=String(d.get('brandName')||'').trim();
 const fail=m=>error.textContent=m;if(!name||name.length>60)return fail('Enter a brand name of up to 60 characters.');
 if(Object.keys(vehicleCatalog()).some(b=>b.toLowerCase()===name.toLowerCase()&&b!==original))return fail('This brand already exists. Open it to edit its logo.');
 const entries=state.settings.brandCatalog||[];if(!entries.some(b=>b.name===original)&&entries.length>=20)return fail('You can customize up to 20 brands per workshop.');
 const models=[...new Set(String(d.get('models')||'').split(/[\n,]/).map(x=>x.trim()).filter(Boolean))];if(models.length>150||models.some(x=>x.length>80))return fail('Use up to 150 models, with each name under 80 characters.');
 const updated=entries.filter(b=>b.name!==original);updated.push({name,models,logo:brandLogoDraft});if(JSON.stringify(updated).length>600000)return fail('The saved logos are too large. Use smaller images.');
 state.settings.brandCatalog=updated;closeModal();query='';render();toast('Brand saved.');
});
